nodes.create.args:
位置参数数组：[input: {
    /** 新节点的非空显示名；允许与其它节点重名，创建结果 handle 才是后续操作的身份。 */
    name: string;
    /** 要挂接的父节点身份；显式 null 表示根。新节点以单位局部变换创建。 */
    parent: NodeHandle | null;
    /** 可选节点自身活动开关，默认 true；不会修改父节点或兄弟节点的开关。 */
    active?: boolean;
}]
args[0] input: 节点名称、显式父级及可选活动开关；parent 为 null 创建在根，初始局部变换为单位变换。
类型约定：
NodeHandle：当前文档中的节点身份；文档 ID 不变则句柄不变，ID 复用后定位新节点。
WPrefab 宿主返回 n12，直接来自文档 node.id；目标由外层操作选择，不是 Unity GetInstanceID()。

nodes.update.args:
位置参数数组：[nodes: NodeHandle[], patch: {
    /** 可选的新显示名，必须非空；省略保留原名，不改变节点身份。 */
    name?: string;
    /** 可选自身活动开关；省略保留原配置，不级联改写后代的 isActive。 */
    active?: boolean;
    /** 可选 Unity Layer 整数编号，范围 0..31；省略保留原 Layer。 */
    layer?: number;
    /** 可选非空 Unity Tag 字符串；省略保留原 Tag，不用来修改组件或层级。 */
    tag?: string;
}]
args[0] nodes: 当前目标中的节点身份列表，原样使用 SDK 返回的 NodeHandle；当前目标中不存在对应 ID 时拒绝。
args[1] patch: 要修改的 name/active/layer/tag 字段；省略字段保留，层级与变换使用专门方法。
类型约定：
NodeHandle：当前文档中的节点身份；文档 ID 不变则句柄不变，ID 复用后定位新节点。
WPrefab 宿主返回 n12，直接来自文档 node.id；目标由外层操作选择，不是 Unity GetInstanceID()。

transforms.set.args:
位置参数数组：[input: {
    /** 待操作的节点身份列表；subtree 范围下祖先与后代同时选中会归一化，避免重复施加变换。 */
    nodes: NodeHandle[];
    /** world 使用世界坐标，local 使用父节点坐标；每次必须明确指定。 */
    space: "world" | "local";
    /** 省略时默认为 subtree，连同后代施加变换；显式 node-only 只改选中节点并保持后代世界变换。
    模型整体布局使用 subtree；需要后代保持世界姿态时显式使用 node-only。 */
    scope?: "subtree" | "node-only";
} & {
    /** 要覆盖的 TRS 分量；position/rotation/scale 可分别省略，省略的分量保持原值，向量本身须完整。 */
    value: Partial<{
        /** 所选 space 中的位置，单位为米；local 相对于父节点，world 相对于世界原点。 */
        position: {
            /** X 分量，必须为有限数；位置/平移使用米，缩放使用无单位倍率，作为缩放时不能为零。 */
            x: number;
            /** Y 分量，必须为有限数；Unity 的向上轴为 Y，位置/平移使用米，缩放使用无单位倍率。 */
            y: number;
            /** Z 分量，必须为有限数；位置/平移使用米，缩放使用无单位倍率，作为缩放时不能为零。 */
            z: number;
        };
        /** 所选 space 中的单位四元数，分量顺序为 xyzw；不能传欧拉角。 */
        rotation: {
            /** 四元数向量部分的 X 分量，无单位；与 y/z/w 共同构成归一化旋转，不是以米为单位的位置。 */
            x: number;
            /** 四元数向量部分的 Y 分量，无单位；表示旋转分量，不是欧拉角或 Y 轴平移。 */
            y: number;
            /** 四元数向量部分的 Z 分量，无单位；必须与其它分量一起有限且归一化。 */
            z: number;
            /** 单位四元数的标量分量；与 x/y/z 一起满足归一化约束，单位旋转为 {x:0,y:0,z:0,w:1}。 */
            w: number;
        };
        /** 所选 space 中的缩放，无单位；local 为局部缩放，world 为有符号 lossyScale，分量不能为零。 */
        scale: {
            /** X 分量，必须为有限数；位置/平移使用米，缩放使用无单位倍率，作为缩放时不能为零。 */
            x: number;
            /** Y 分量，必须为有限数；Unity 的向上轴为 Y，位置/平移使用米，缩放使用无单位倍率。 */
            y: number;
            /** Z 分量，必须为有限数；位置/平移使用米，缩放使用无单位倍率，作为缩放时不能为零。 */
            z: number;
        };
    }>;
}]
args[0] input: 目标、空间、作用范围及要覆盖的 TRS 分量；未提供分量保留当前值。
类型约定：
NodeHandle：当前文档中的节点身份；文档 ID 不变则句柄不变，ID 复用后定位新节点。
WPrefab 宿主返回 n12，直接来自文档 node.id；目标由外层操作选择，不是 Unity GetInstanceID()。

assets.instantiateModel.args:
位置参数数组：[input: {
    /** 远程资源使用已发布的固定 URI 句柄，包内资源使用当前文档的 rN 句柄；不接受来源描述对象或本地文件路径。 */
    resource: ResourceHandle;
    /** 实例根要挂接的父节点身份；显式 null 放在场景根，不能传数字 parentId。 */
    parent: NodeHandle | null;
    /** 可选实例根展示名；普通模型省略时使用 Model。UI 实例根始终使用资源 payload 的 uiId，若显式传 name，必须与 uiId 完全一致，否则拒绝；通过 instantiateModel 装配 UI 资源时也遵守此规则。 */
    name?: string;
}]
args[0] input: 已发布 URI 或当前包内模型句柄、显式父级和可选展示名；普通模型默认名为 Model，若资源为 UI 则遵守 UI 命名规则。
类型约定：
NodeHandle：当前文档中的节点身份；文档 ID 不变则句柄不变，ID 复用后定位新节点。
WPrefab 宿主返回 n12，直接来自文档 node.id；目标由外层操作选择，不是 Unity GetInstanceID()。
ResourceHandle：资源来源身份；远程值为固定 URI，包内值为 r12，直接来自当前文档 resourceRefs 中的 ID。

assets.instantiateModel.returns:
{
    /** 成功操作后的模型或 UI 根节点身份；用该句柄继续查询和编辑，不自行猜测 Runtime 数字 ID。 */
    root: NodeHandle;
}
